  void addField(String label,View e){root.addView(text(label,14));root.addView(e);}
  void sentForm(){base("संघ में भेजा गया दूध");EditText date=field("तारीख YYYY-MM-DD",today()),challan=field("Challan No.",""),milk=field("Milk KG",""),fat=field("FAT %",""),snf=field("SNF %","");Spinner part=spinner(new String[]{"Single","Rear","Front"});addField("तारीख",date);addField("Challan No.",challan);addField("Particular",part);addField("Milk (KG)",milk);addField("FAT %",fat);addField("SNF %",snf);TextView preview=text("Fat KG और SNF KG अपने-आप निकलेंगे।",14);root.addView(preview);TextWatcherLite.watch(new EditText[]{milk,fat,snf},()->preview.setText(String.format(Locale.US,"Fat KG: %.3f    SNF KG: %.3f",Calc.fatKg(num(milk),num(fat)),Calc.snfKg(num(milk),num(snf)) )));root.addView(button("सेव करें",()->{if(!validDate(val(date))){msg("तारीख YYYY-MM-DD में सही भरें");return;}ContentValues c=new ContentValues();c.put("date",val(date));c.put("challan",val(challan));c.put("particular",part.getSelectedItem().toString());c.put("milk",num(milk));c.put("fat_pct",num(fat));c.put("snf_pct",num(snf));c.put("fat_kg",Calc.fatKg(num(milk),num(fat)));c.put("snf_kg",Calc.snfKg(num(milk),num(snf)));db.insert("sent",c);msg("एंट्री सेव हो गई");home();}));root.addView(button("वापस",()->home()));}
  void receivedForm(){base("समिति से प्राप्त दूध");EditText date=field("तारीख YYYY-MM-DD",today()),milk=field("Milk KG",""),fat=field("FAT %",""),snf=field("SNF %",""),fatkg=field("Fat KG",""),snfkg=field("SNF KG","");Spinner shift=spinner(new String[]{"Morning","Evening"});addField("तारीख",date);addField("पाली",shift);addField("Milk (KG)",milk);addField("FAT %",fat);addField("SNF %",snf);addField("Fat KG (मैन्युअल)",fatkg);addField("SNF KG (मैन्युअल)",snfkg);root.addView(button("सेव करें",()->{if(!validDate(val(date))){msg("तारीख YYYY-MM-DD में सही भरें");return;}ContentValues c=new ContentValues();c.put("date",val(date));c.put("shift",shift.getSelectedItem().toString());c.put("milk",num(milk));c.put("fat_pct",num(fat));c.put("snf_pct",num(snf));c.put("fat_kg",num(fatkg));c.put("snf_kg",num(snfkg));db.insert("received",c);msg("एंट्री सेव हो गई");home();}));root.addView(button("वापस",()->home()));}
  void balanceForm(){base("मासिक पूर्व शेष / अंतिम शेष");EditText month=field("महीना YYYY-MM",new SimpleDateFormat("yyyy-MM",Locale.US).format(new Date()));EditText[] f=new EditText[10];String[] labels={"पूर्व शेष Milk KG","पूर्व शेष FAT %","पूर्व शेष SNF %","पूर्व शेष Fat KG","पूर्व शेष SNF KG","अंतिम शेष Milk KG","अंतिम शेष FAT %","अंतिम शेष SNF %","अंतिम शेष Fat KG","अंतिम शेष SNF KG"};addField("महीना",month);String[] cols={"opening_milk","opening_fat_pct","opening_snf_pct","opening_fat_kg","opening_snf_kg","closing_milk","closing_fat_pct","closing_snf_pct","closing_fat_kg","closing_snf_kg"};for(int i=0;i<f.length;i++){f[i]=field(labels[i],"0");addField(labels[i],f[i]);}month.setOnFocusChangeListener((view,focused)->{if(!focused && val(month).matches("\\d{4}-\\d{2}")){double[] oldBal=balance(val(month));for(int j=0;j<f.length;j++)f[j].setText(f(oldBal[j]));}});root.addView(button("पुराने महीने का शेष लोड करें",()->{if(!val(month).matches("\\d{4}-\\d{2}")){msg("महीना YYYY-MM में भरें");return;}double[] oldBal=balance(val(month));for(int j=0;j<f.length;j++)f[j].setText(f(oldBal[j]));}));root.addView(button("सेव करें",()->{if(!val(month).matches("\\d{4}-\\d{2}")){msg("महीना YYYY-MM में भरें");return;}ContentValues c=new ContentValues();c.put("month",val(month));for(int i=0;i<f.length;i++)c.put(cols[i],num(f[i]));db.getWritableDatabase().insertWithOnConflict("balance",null,c,android.database.sqlite.SQLiteDatabase.CONFLICT_REPLACE);msg("मासिक शेष सेव हो गया");home();}));root.addView(button("वापस",()->home()));}
  Spinner spinner(String[] a){Spinner s=new Spinner(this);ArrayAdapter<String> ad=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a);s.setAdapter(ad);return s;}
  void recordsMenu(){base("पुराना डेटा");root.addView(button("संघ में भेजा गया दूध",()->listTable("sent")));root.addView(button("समिति से प्राप्त दूध",()->listTable("received")));root.addView(button("वापस",()->home()));}
  void listTable(String table){base(table.equals("sent")?"संघ में भेजा गया दूध — रिकॉर्ड":"समिति से प्राप्त दूध — रिकॉर्ड");Cursor c=db.all(table);while(c.moveToNext()){String line="ID "+c.getLong(c.getColumnIndexOrThrow("id"))+" | "+c.getString(c.getColumnIndexOrThrow("date"))+" | Milk "+c.getDouble(c.getColumnIndexOrThrow("milk"))+" KG";root.addView(text(line,14));final long id=c.getLong(c.getColumnIndexOrThrow("id"));root.addView(button("एडिट करें ID "+id,()->editRecord(table,id)));root.addView(button("डिलीट करें ID "+id,()->new AlertDialog.Builder(this).setMessage("यह रिकॉर्ड हटाएँ?").setNegativeButton("नहीं",null).setPositiveButton("हाँ",(d,w)->{db.delete(table,id);listTable(table);}).show()));}c.close();root.addView(button("वापस",()->recordsMenu()));}
  void editRecord(String table,long id){Cursor c=db.getReadableDatabase().rawQuery("SELECT * FROM "+table+" WHERE id=?",new String[]{String.valueOf(id)});if(!c.moveToFirst()){c.close();msg("रिकॉर्ड नहीं मिला");return;}String date=c.getString(c.getColumnIndexOrThrow("date"));double milkV=c.getDouble(c.getColumnIndexOrThrow("milk")),fatV=c.getDouble(c.getColumnIndexOrThrow("fat_pct")),snfV=c.getDouble(c.getColumnIndexOrThrow("snf_pct")),fatKgV=c.getDouble(c.getColumnIndexOrThrow("fat_kg")),snfKgV=c.getDouble(c.getColumnIndexOrThrow("snf_kg"));String challanV="",partV="Single",shiftV="Morning";if(table.equals("sent")){challanV=c.getString(c.getColumnIndexOrThrow("challan"));partV=c.getString(c.getColumnIndexOrThrow("particular"));}else shiftV=c.getString(c.getColumnIndexOrThrow("shift"));c.close();base("रिकॉर्ड एडिट करें — ID "+id);EditText dt=field("तारीख YYYY-MM-DD",date),milk=field("Milk KG",f(milkV)),fat=field("FAT %",f(fatV)),snf=field("SNF %",f(snfV)),fatkg=null,snfkg=null,challan=null;addField("तारीख",dt);Spinner choice;if(table.equals("sent")){challan=field("Challan No.",challanV);addField("Challan No.",challan);choice=spinner(new String[]{"Single","Rear","Front"});choice.setSelection(Math.max(0,Arrays.asList("Single","Rear","Front").indexOf(partV)));addField("Particular",choice);}else{choice=spinner(new String[]{"Morning","Evening"});choice.setSelection(shiftV.equals("Evening")?1:0);addField("पाली",choice);}addField("Milk (KG)",milk);addField("FAT %",fat);addField("SNF %",snf);if(table.equals("received")){fatkg=field("Fat KG (मैन्युअल)",f(fatKgV));snfkg=field("SNF KG (मैन्युअल)",f(snfKgV));addField("Fat KG",fatkg);addField("SNF KG",snfkg);}final EditText challanField=challan,fatKgField=fatkg,snfKgField=snfkg;root.addView(button("बदलाव सेव करें",()->{if(!validDate(val(dt))){msg("तारीख YYYY-MM-DD में सही भरें");return;}ContentValues v=new ContentValues();v.put("date",val(dt));v.put("milk",num(milk));v.put("fat_pct",num(fat));v.put("snf_pct",num(snf));if(table.equals("sent")){v.put("challan",val(challanField));v.put("particular",choice.getSelectedItem().toString());v.put("fat_kg",Calc.fatKg(num(milk),num(fat)));v.put("snf_kg",Calc.snfKg(num(milk),num(snf)));}else{v.put("shift",choice.getSelectedItem().toString());v.put("fat_kg",num(fatKgField));v.put("snf_kg",num(snfKgField));}db.update(table,id,v);msg("रिकॉर्ड अपडेट हो गया");listTable(table);}));root.addView(button("रद्द करें",()->listTable(table)));}
  void settingsForm(){base("रिपोर्ट विवरण");EditText rootNo=field("Root No.",db.setting("root_no","Root No-4A")),center=field("केंद्र का नाम",db.setting("center","मोरवाड़ा बल्क कूलर परिचालन केंद्र")),date=field("PDF पर Date (मैन्युअल)",db.setting("report_date",""));addField("Root No.",rootNo);addField("केंद्र का नाम",center);addField("PDF पर Date",date);root.addView(button("सेव करें",()->{db.putSetting("root_no",val(rootNo));db.putSetting("center",val(center));db.putSetting("report_date",val(date));msg("सेटिंग सेव हो गई");home();}));root.addView(button("वापस",()->home()));}
  void reportForm(){base("रिपोर्ट बनाएं");EditText from=field("शुरुआती तारीख YYYY-MM-DD",today()),to=field("अंतिम तारीख YYYY-MM-DD",today());Spinner fs=spinner(new String[]{"Morning","Evening"}),ts=spinner(new String[]{"Morning","Evening"});EditText month=field("मासिक शेष के लिए महीना YYYY-MM",today().substring(0,7));addField("शुरुआती तारीख",from);root.addView(fs);addField("अंतिम तारीख",to);root.addView(ts);addField("पूर्व/अंतिम शेष वाला महीना",month);root.addView(text("पाली की सीमा inclusive है। समिति का डेटा तारीख व पाली से जुड़ेगा। पूर्व/अंतिम शेष केवल पूरे महीने की रिपोर्ट में जुड़ेगा; 7/15 दिन की रिपोर्ट में मासिक शेष नहीं जोड़ा जाएगा।",14));root.addView(button("सारांश देखें",()->summary(from,to,fs,ts,month,false)));root.addView(button("PDF रिपोर्ट बनाएं",()->summary(from,to,fs,ts,month,true)));root.addView(button("Excel फ़ाइल (.xlsx) एक्सपोर्ट करें",()->exportXlsx(from,to,fs,ts)));root.addView(button("CSV एक्सपोर्ट (वैकल्पिक)",()->exportCsv(from,to,fs,ts)));root.addView(button("वापस",()->home()));}
  static class Totals { double milk,fatKg,snfKg,fatPct,snfPct; }
  Totals sumRows(String table,String from,String to,Spinner fs,Spinner ts){Totals t=new Totals();Cursor c=db.getReadableDatabase().rawQuery("SELECT date, milk, fat_pct, snf_pct, fat_kg, snf_kg, "+(table.equals("received")?"shift":"'All'")+" FROM "+table+" WHERE date>=? AND date<=? ORDER BY date,id",new String[]{from,to});while(c.moveToNext()){String date=c.getString(0),shift=c.getString(6); if(table.equals("received")){ if(date.equals(from) && (fs.getSelectedItemPosition()==1 && shift.equals("Morning"))) continue; if(date.equals(to) && (ts.getSelectedItemPosition()==0 && shift.equals("Evening"))) continue; if(from.equals(to) && fs.getSelectedItemPosition()>ts.getSelectedItemPosition()) continue; } t.milk+=c.getDouble(1);t.fatKg+=c.getDouble(4);t.snfKg+=c.getDouble(5);}c.close();if(t.milk>0){t.fatPct=t.fatKg/t.milk*100;t.snfPct=t.snfKg/t.milk*100;}return t;}
  double[] balance(String month){double[] a=new double[10];Cursor c=db.monthBalance(month);if(c.moveToFirst()){String[] cols={"opening_milk","opening_fat_pct","opening_snf_pct","opening_fat_kg","opening_snf_kg","closing_milk","closing_fat_pct","closing_snf_pct","closing_fat_kg","closing_snf_kg"};for(int i=0;i<cols.length;i++)a[i]=c.getDouble(c.getColumnIndexOrThrow(cols[i]));}c.close();return a;}
  void summary(EditText from,EditText to,Spinner fs,Spinner ts,EditText month,boolean makePdf){String a=val(from),b=val(to),m=val(month);if(!validDate(a)||!validDate(b)||a.compareTo(b)>0||!validMonth(m)){msg("तारीख और महीना सही भरें");return;}Totals received=sumRows("received",a,b,fs,ts),sent=sumRows("sent",a,b,fs,ts);boolean fullMonth=isFullMonthRange(a,b,m);double[] bal=fullMonth?balance(m):new double[10];double totalMilk=bal[0]+received.milk,totalFat=bal[3]+received.fatKg,totalSnf=bal[4]+received.snfKg;double totalRemain=sent.milk+bal[5],remainFat=sent.fatKg+bal[8],remainSnf=sent.snfKg+bal[9];double loss=totalRemain-totalMilk,lossFat=remainFat-totalFat,lossSnf=remainSnf-totalSnf;
    if(makePdf){createPdf(a,b,m,received,sent,bal,totalMilk,totalFat,totalSnf,totalRemain,remainFat,remainSnf,loss,lossFat,lossSnf);return;}
    base("चयनित अवधि का सारांश");root.addView(text("अवधि: "+a+" से "+b+" | पाली: "+fs.getSelectedItem()+" से "+ts.getSelectedItem(),15));if(!fullMonth)root.addView(text("नोट: यह आंशिक अवधि है; मासिक पूर्व/अंतिम शेष शामिल नहीं हैं।",14));root.addView(text(String.format(Locale.US,"समिति से प्राप्त दूध %.3f KG | Fat %.3f KG | SNF %.3f KG",received.milk,received.fatKg,received.snfKg),15));root.addView(text(String.format(Locale.US,"संघ में भेजा दूध %.3f KG | Fat %.3f KG | SNF %.3f KG",sent.milk,sent.fatKg,sent.snfKg),15));root.addView(text(String.format(Locale.US,"कुल दूध (1+2): %.3f KG",totalMilk),15));root.addView(text(String.format(Locale.US,"कुल शेष (4+5): %.3f KG",totalRemain),15));root.addView(text(String.format(Locale.US,"हस्तगत क्षति (फोटो के अनुसार 6−3): %.3f KG | Fat %.3f KG | SNF %.3f KG",loss,lossFat,lossSnf),15));root.addView(button("PDF बनाएं",()->createPdf(a,b,m,received,sent,bal,totalMilk,totalFat,totalSnf,totalRemain,remainFat,remainSnf,loss,lossFat,lossSnf)));root.addView(button("वापस",()->reportForm()));}
  void createPdf(String from,String to,String month,Totals received,Totals sent,double[] bal,double totalMilk,double totalFat,double totalSnf,double totalRemain,double remainFat,double remainSnf,double loss,double lossFat,double lossSnf){try{android.graphics.pdf.PdfDocument doc=new android.graphics.pdf.PdfDocument();android.graphics.pdf.PdfDocument.PageInfo info=new android.graphics.pdf.PdfDocument.PageInfo.Builder(842,595,1).create();android.graphics.pdf.PdfDocument.Page page=doc.startPage(info);android.graphics.Canvas canvas=page.getCanvas();android.graphics.Paint paint=new android.graphics.Paint(3);paint.setColor(Color.BLACK);paint.setTextSize(15);paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));canvas.drawText("मिथिला दुग्ध उत्पादन सहकारी संघ लिमिटेड, समस्तीपुर",190,32,paint);paint.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));paint.setTextSize(11);canvas.drawText(db.setting("center","मोरवाड़ा बल्क कूलर परिचालन केंद्र"),290,52,paint);canvas.drawText("दुग्ध हस्तगत क्षति प्रतिवेदन",345,75,paint);canvas.drawText("अवधि: "+from+" से "+to,30,100,paint);canvas.drawText("Month: "+month+"     Root No: "+db.setting("root_no","Root No-4A")+"     Date: "+db.setting("report_date",""),30,120,paint);if(!isFullMonthRange(from,to,month)){paint.setTextSize(10);canvas.drawText("नोट: आंशिक अवधि — मासिक पूर्व/अंतिम शेष शामिल नहीं हैं।",30,137,paint);}
    String[] heads={"क्र.","विवरणी","मात्रा KG","वसा %","SNF %","वसा KG","वसा रहित KG","अभ्युक्ति"};int[] xs={25,65,300,385,455,525,605,700};paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));paint.setTextSize(10);for(int i=0;i<heads.length;i++)canvas.drawText(heads[i],xs[i],150,paint);canvas.drawLine(20,157,820,157,paint);paint.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));
    String[][] rows={{"1","पूर्व शेष दूध",f(bal[0]),f(bal[1]),f(bal[2]),f(bal[3]),f(bal[4]),""},{"2","समिति से प्राप्त दूध",f(received.milk),f(received.fatPct),f(received.snfPct),f(received.fatKg),f(received.snfKg),""},{"3","कुल दूध (1+2)",f(totalMilk),"-","-",f(totalFat),f(totalSnf),""},{"4","संघ में भेजा गया दूध",f(sent.milk),f(sent.fatPct),f(sent.snfPct),f(sent.fatKg),f(sent.snfKg),""},{"5","अंतिम शेष",f(bal[5]),f(bal[6]),f(bal[7]),f(bal[8]),f(bal[9]),""},{"6","कुल शेष (4+5)",f(totalRemain),"-","-",f(remainFat),f(remainSnf),""},{"7","हस्तगत क्षति (6-3)",f(loss),"-","-",f(lossFat),f(lossSnf),""}};int y=180;for(String[] row:rows){for(int i=0;i<row.length;i++){paint.setTextSize(i==1?10:9);canvas.drawText(row[i],xs[i],y,paint);}canvas.drawLine(20,y+8,820,y+8,paint);y+=38;}canvas.drawText("सचिव का हस्ताक्षर: ____________________",610,520,paint);doc.finishPage(page);java.io.File file=new java.io.File(getExternalFilesDir(null),"Milk_Handling_Loss_"+from+"_"+to+".pdf");java.io.FileOutputStream out=new java.io.FileOutputStream(file);doc.writeTo(out);out.close();doc.close();android.net.Uri uri=androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".provider",file);Intent send=new Intent(Intent.ACTION_SEND);send.setType("application/pdf");send.putExtra(Intent.EXTRA_STREAM,uri);send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(send,"PDF साझा करें / सेव करें"));}catch(Exception e){msg("PDF नहीं बन सकी: "+e.getMessage());}}
  String f(double d){return String.format(Locale.US,"%.3f",d);}
  void exportCsv(EditText from,EditText to,Spinner fs,Spinner ts){try{String a=val(from),b=val(to);StringBuilder csv=new StringBuilder("Date,Type,Challan,Particular,Shift,Milk KG,FAT %,SNF %,Fat KG,SNF KG\n");for(String table:new String[]{"sent","received"}){Cursor c=db.all(table);while(c.moveToNext()){String date=c.getString(c.getColumnIndexOrThrow("date"));if(!a.isEmpty()&&date.compareTo(a)<0||!b.isEmpty()&&date.compareTo(b)>0)continue;if(table.equals("received")){String sh=c.getString(c.getColumnIndexOrThrow("shift"));if(date.equals(a)&&fs.getSelectedItemPosition()==1&&sh.equals("Morning"))continue;if(date.equals(b)&&ts.getSelectedItemPosition()==0&&sh.equals("Evening"))continue;}csv.append(date).append(',').append(table).append(',');csv.append(table.equals("sent")?c.getString(c.getColumnIndexOrThrow("challan")):"").append(',').append(table.equals("sent")?c.getString(c.getColumnIndexOrThrow("particular")):"").append(',').append(table.equals("received")?c.getString(c.getColumnIndexOrThrow("shift")):"").append(',');for(String col:new String[]{"milk","fat_pct","snf_pct","fat_kg","snf_kg"})csv.append(c.getDouble(c.getColumnIndexOrThrow(col))).append(',');csv.append("\n");}c.close();}java.io.File file=new java.io.File(getExternalFilesDir(null),"Milk_Handling_Loss.csv");java.nio.file.Files.write(file.toPath(),csv.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));android.net.Uri uri=androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".provider",file);Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/csv");send.putExtra(Intent.EXTRA_STREAM,uri);send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(send,"CSV साझा करें"));}catch(Exception e){msg("CSV export नहीं हो सका: "+e.getMessage());}}
  String xml(String s){if(s==null)return "";return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}
  String colName(int n){StringBuilder b=new StringBuilder();while(n>0){int r=(n-1)%26;b.insert(0,(char)('A'+r));n=(n-1)/26;}return b.toString();}
  String sheetXml(String table,String from,String to,Spinner fs,Spinner ts){StringBuilder x=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData>");String[] headers=table.equals("sent")?new String[]{"Date","Type","Challan No.","Particular","Milk KG","FAT %","SNF %","Fat KG","SNF KG"}:new String[]{"Date","Type","Shift","Milk KG","FAT %","SNF %","Fat KG","SNF KG"};x.append("<row r=\"1\">");for(int i=0;i<headers.length;i++)x.append(cell(i+1,1,headers[i],true));x.append("</row>");Cursor c=db.all(table);int row=2;while(c.moveToNext()){String date=c.getString(c.getColumnIndexOrThrow("date"));if(!from.isEmpty()&&date.compareTo(from)<0||!to.isEmpty()&&date.compareTo(to)>0)continue;if(table.equals("received")){String sh=c.getString(c.getColumnIndexOrThrow("shift"));if(date.equals(from)&&fs.getSelectedItemPosition()==1&&sh.equals("Morning"))continue;if(date.equals(to)&&ts.getSelectedItemPosition()==0&&sh.equals("Evening"))continue;}x.append("<row r=\"").append(row).append("\">");int j=1;x.append(cell(j++,row,date,true));x.append(cell(j++,row,table.equals("sent")?"Sent to Union":"Received from Society",true));if(table.equals("sent")){x.append(cell(j++,row,c.getString(c.getColumnIndexOrThrow("challan")),true));x.append(cell(j++,row,c.getString(c.getColumnIndexOrThrow("particular")),true));}else{x.append(cell(j++,row,c.getString(c.getColumnIndexOrThrow("shift")),true));}for(String name:new String[]{"milk","fat_pct","snf_pct","fat_kg","snf_kg"})x.append(cell(j++,row,Double.toString(c.getDouble(c.getColumnIndexOrThrow(name))),false));x.append("</row>");row++;}c.close();return x.append("</sheetData></worksheet>").toString();}
  String cell(int col,int row,String value,boolean string){String ref=colName(col)+row;if(string)return "<c r=\""+ref+"\" t=\"inlineStr\"><is><t xml:space=\"preserve\">"+xml(value)+"</t></is></c>";return "<c r=\""+ref+"\"><v>"+xml(value)+"</v></c>";}
  void zipEntry(java.util.zip.ZipOutputStream z,String name,String value)throws Exception{z.putNextEntry(new java.util.zip.ZipEntry(name));z.write(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));z.closeEntry();}
